N=27
g=[[4]*N for _ in range(N)]
for i in range(N): g[13][i]=1; g[i][13]=1
# Top-left reference pattern exactly
for r in (3,4):
    for c in (3,4): g[r][c]=8
    for c in (5,6): g[r][c]=7
for r in (5,6):
    for c in range(1,5): g[r][c]=9
    for c in (5,6): g[r][c]=2
for r in (7,8):
    for c in (5,6): g[r][c]=1
# target cores
cores=[(4,19,3,'h'),(19,18,4,'r'),(21,5,1,'v')]
for r,c,n,orient in cores:
    for y in range(n):
        for x in range(n): g[r+y][c+x]=2
# key tiles relative to core: color, logical row offset, logical col offset
features=[(8,-1,-1),(7,-1,0),(9,0,-2),(9,0,-1),(1,1,0)]
for r,c,n,orient in cores:
    for color,dy,dx in features:
        if orient=='h': dx=-dx
        elif orient=='v': dy=-dy
        elif orient=='r': dy=-dy; dx=-dx
        for yy in range(n):
            for xx in range(n):
                rr=r+dy*n+yy; cc=c+dx*n+xx
                if 0<=rr<N and 0<=cc<N and not (r<=rr<r+n and c<=cc<c+n):
                    g[rr][cc]=color
import json
print(json.dumps(g))
